async function sha256Hex(bytes: Uint8Array): Promise<string> {
  const digest = await crypto.subtle.digest('SHA-256', bytes);
  return [...new Uint8Array(digest)].map((b) => b.toString(16).padStart(2, '0')).join('');
}

Deno.serve(async (req) => {
  try {
    const base44 = createClientFromRequest(req);
    const caller = await base44.auth.me();
    if (!caller) return Response.json({ error: 'Unauthorized' }, { status: 401 });
    // Platform admin only — checked before any service-role data access.
    if (caller.role !== 'admin') return Response.json({ error: 'Forbidden' }, { status: 403 });

    const body = await req.json().catch(() => ({}));
    if (body.mode !== undefined && !['dry_run', 'apply'].includes(body.mode)) {
      return Response.json({ error: "mode must be 'dry_run' or 'apply'" }, { status: 400 });
    }
    const mode = body.mode === 'apply' ? 'apply' : 'dry_run'; // safe default

    if (CATALOG.length !== EXPECTED_TEMPLATE_COUNT) {
      return Response.json({ error: `Embedded catalog corrupted: expected ${EXPECTED_TEMPLATE_COUNT} templates, found ${CATALOG.length}.` }, { status: 500 });
    }

    const sr = base44.asServiceRole;

    // 1) Verify EVERY asset hash before any write.
    const assetFailures: string[] = [];
    for (const t of CATALOG) {
      try {
        const signed = await sr.integrations.Core.CreateFileSignedUrl({ file_uri: t.file_uri });
        const res = await fetch(signed.signed_url);
        if (!res.ok) { assetFailures.push(`${t.template_key}: asset fetch failed (${res.status})`); continue; }
        const bytes = new Uint8Array(await res.arrayBuffer());
        const hash = await sha256Hex(bytes);
        if (hash !== t.normalized_sha256) assetFailures.push(`${t.template_key}: hash mismatch`);
      } catch (e) {
        assetFailures.push(`${t.template_key}: ${e.message}`);
      }
    }
    if (assetFailures.length > 0) {
      return Response.json({ error: 'Asset verification failed — no writes performed.', failures: assetFailures }, { status: 409 });
    }

    // 2) Plan against existing canonical records (idempotency key: template_key + template_version + normalized_sha256).
    const existing = await sr.entities.DocumentTemplate.filter({ template_version: TEMPLATE_VERSION }, null, 500).catch(() => []);
    const byKey = new Map(existing.filter((e: any) => e.template_key).map((e: any) => [`${e.template_key}|${e.template_version}`, e]));

    const toCreate: any[] = [];
    const unchanged: string[] = [];
    const conflicts: string[] = [];
    for (const t of CATALOG) {
      const found: any = byKey.get(`${t.template_key}|${TEMPLATE_VERSION}`);
      if (!found) {
        toCreate.push({
          title: t.title,
          template_key: t.template_key,
          template_version: TEMPLATE_VERSION,
          document_id: t.document_id,
          document_type: t.document_type,
          primary_control_id: t.primary_control_id,
          control_ids: t.control_ids,
          cmmc_levels: t.cmmc_levels,
          control_alignment_note: t.control_alignment_note,
          required_source_fields: t.tags.filter((tag: string) => !APPROVAL_FIELDS.includes(tag) && !AUTO_FIELDS.includes(tag)),
          required_approval_fields: APPROVAL_FIELDS,
          normalized_sha256: t.normalized_sha256,
          source_sha256: t.source_sha256,
          source_zip_sha256: SOURCE_ZIP_SHA256,
          asset_path: t.asset_path,
          file_uri: t.file_uri,
          library_version: LIBRARY_VERSION,
          active: true,
          category: 'Canonical Policy Library',
          version: '1.0',
        });
      } else if (found.normalized_sha256 === t.normalized_sha256) {
        unchanged.push(t.template_key);
      } else {
        conflicts.push(`${t.template_key}: existing ${TEMPLATE_VERSION} record has a different normalized_sha256`);
      }
    }

    const counts = {
      mode,
      assets_verified: CATALOG.length,
      planned_create: toCreate.length,
      unchanged: unchanged.length,
      conflicts: conflicts.length,
      conflict_details: conflicts,
      created: 0,
    };

    if (mode === 'dry_run') {
      return Response.json({ ...counts, message: 'Dry run only — no records were written.' });
    }
    if (conflicts.length > 0) {
      return Response.json({ ...counts, error: 'Conflicts detected — apply aborted with zero writes. Resolve by importing a new template_version; existing templates are never overwritten or deleted.' }, { status: 409 });
    }

    for (let i = 0; i < toCreate.length; i += BATCH_SIZE) {
      const batch = toCreate.slice(i, i + BATCH_SIZE);
      const created = await sr.entities.DocumentTemplate.bulkCreate(batch);
      counts.created += Array.isArray(created) ? created.length : batch.length;
    }
    return Response.json({ ...counts, message: `Imported ${counts.created} templates; ${counts.unchanged} unchanged.` });
  } catch (error) {
    return Response.json({ error: error.message }, { status: 500 });
  }
});